/* page.tsx */
'use client'


import { useEffect, useMemo, useState } from 'react'
import { AlertTriangle, ArrowLeft, ArrowRight, BarChart3, Check, CheckCircle2, ChevronDown, CircleAlert, Clipboard, Download, FileText, Filter, Gauge, Globe2, LayoutDashboard, MapPin, Menu, RefreshCw, Search, ShieldCheck, Sparkles, Star, Target, TrendingUp, Users, X } from 'lucide-react'
import { analyze, ApiError, discover, findOwnBusiness, getConfig, getReviews, quickCompare } from '@/lib/api'
import type { Config, Entity, Place, Report, Review, ReviewWindowKey } from '@/lib/types'
import { ContentIntelligence } from '@/components/content-intelligence'
import { BusinessPicker } from '@/components/business-picker'
import { ReportVisuals } from '@/components/report-visuals'
import { QualityPanel } from '@/components/quality-panel'
const fallbackConfig: Config = { limits: { min_competitors: 1, max_competitors: 4, max_discover_results: 15, max_reviews_per_place: 200 }, review_windows: [{ key: '30d', label: 'Last 30 days', default: true }, { key: '60d', label: 'Last 60 days' }, { key: '90d', label: 'Last 90 days' }, { key: 'all', label: 'All available' }], theme_taxonomy: [], health_score: { weights: {}, labels: {} }, metrics: [], goal_suggestions: ['Get more reviews', 'Improve customer experience', 'Justify premium pricing', 'Increase repeat visits'], business_type_suggestions: ['Restaurant', 'Gym', 'Salon', 'Retail store', 'Professional service'], report_languages: ['English'] }
type Step = 'setup' | 'discover' | 'options' | 'report'
type Draft = { businessType: string; city: string; country: string; area: string; ownBusiness: Place | null; competitors: Place[]; reviewWindow: ReviewWindowKey; goals: string[]; ownerContext: string; language: string }
const emptyDraft: Draft = { businessType: '', city: '', country: '', area: '', ownBusiness: null, competitors: [], reviewWindow: '30d', goals: [], ownerContext: '', language: 'English' }
const text = (value: unknown, fallback = 'Not available') => typeof value === 'string' && value.trim() ? value : fallback
const number = (value: number | null | undefined, fallback = '—') => value === null || value === undefined ? fallback : value.toLocaleString()
const address = (place: Place | Entity) => place.address?.full || [place.address?.street, place.address?.neighborhood, place.address?.city, place.address?.state, place.address?.postal_code].filter(Boolean).join(', ') || 'Address unavailable'
const safeUrl = (value: string | null | undefined) => value && /^https?:\/\//i.test(value) ? value : null
export default function Page() {  const [step, setStep] = useState<Step>('setup')
  const [config, setConfig] = useState<Config>(fallbackConfig)
  const [draft, setDraft] = useState<Draft>(emptyDraft)
  const [ownQuery, setOwnQuery] = useState('')
  const [ownResults, setOwnResults] = useState<Place[]>([])
  const [places, setPlaces] = useState<Place[]>([])
  const [report, setReport] = useState<Report | null>(null)
  const [loading, setLoading] = useState(false)
  const [ownSearchLoading, setOwnSearchLoading] = useState(false)
  const [competitorSearchLoading, setCompetitorSearchLoading] = useState(false)
  const [error, setError] = useState('')
  const [progress, setProgress] = useState(0)
  const [activeReview, setActiveReview] = useState<{ place: Place | Entity; reviews: Review[] } | null>(null)
  const [reviewLoading, setReviewLoading] = useState(false)
  const [reviewWindow, setReviewWindow] = useState<ReviewWindowKey>('30d')
  useEffect(() => {
    getConfig().then((response) => setConfig({ ...fallbackConfig, ...response })).catch(() => setConfig(fallbackConfig))
  }, [])
  useEffect(() => {
    if (step === 'setup' && !loading) setDraft(emptyDraft)
  }, [step])
  const update = (patch: Partial<Draft>) => setDraft((current) => ({ ...current, ...patch }))
  const validateSetup = () => { if (!draft.businessType.trim() || !draft.city.trim() || !draft.country.trim()) { setError('Business type, city, and country are required.'); return false } return true }
  const runOwnSearch = async () => { if (!ownQuery.trim() || !draft.city || !draft.country) return; setOwnSearchLoading(true); setError(''); try { const response = await findOwnBusiness(ownQuery, draft.city, draft.country, draft.area); setOwnResults(response.places) } catch (cause) { setError(cause instanceof Error ? cause.message : 'Business search failed.') } finally { setOwnSearchLoading(false) } }
  const runCompetitorSearch = async () => { if (!validateSetup()) return; setCompetitorSearchLoading(true); setError(''); try { const response = await discover({ business_type: draft.businessType, city: draft.city, country: draft.country, ...(draft.area ? { area: draft.area } : {}), max_results: Math.min(config.limits.max_discover_results, 50), ...(draft.ownBusiness?.location ? { own_location: draft.ownBusiness.location } : {}), ...(draft.ownBusiness ? { exclude_place_ids: [draft.ownBusiness.place_id] } : {}), skip_closed: true }); setPlaces(response.places); setStep('discover') } catch (cause) { setError(cause instanceof Error ? cause.message : 'Could not discover businesses.') } finally { setCompetitorSearchLoading(false) } }
  const toggleCompetitor = (place: Place) => setDraft((current) => { const exists = current.competitors.some((item) => item.place_id === place.place_id); if (exists) return { ...current, competitors: current.competitors.filter((item) => item.place_id !== place.place_id) }; if (current.competitors.length >= config.limits.max_competitors) return current; return { ...current, competitors: [...current.competitors, place] } })
  const runAnalysis = async () => { if (draft.competitors.length < config.limits.min_competitors) { setError(`Select at least ${config.limits.min_competitors} competitor.`); return } setLoading(true); setError(''); setProgress(0); const timer = window.setInterval(() => setProgress((value) => Math.min(value + 1, 3)), 18000); try { const response = await analyze({ business_type: draft.businessType, city: draft.city, country: draft.country, ...(draft.area ? { area: draft.area } : {}), ...(draft.ownBusiness ? { own_business: { place_id: draft.ownBusiness.place_id, name: draft.ownBusiness.name } } : {}), competitors: draft.competitors.map((place) => ({ place_id: place.place_id, name: place.name, search_rank: place.search_rank })), review_window: draft.reviewWindow, goals: draft.goals, ...(draft.ownerContext ? { owner_context: draft.ownerContext } : {}), report_language: draft.language, include_contacts: true }); setReport(response.report); setStep('report') } catch (cause) { setError(cause instanceof Error ? cause.message : 'The report could not be generated. Retry when ready.') } finally { window.clearInterval(timer); setLoading(false) } }
  const loadReviews = async (place: Place | Entity, windowKey: ReviewWindowKey) => { setReviewLoading(true); setActiveReview((current) => ({ place, reviews: current?.place.place_id === place.place_id ? current.reviews : [] })); try { const response = await getReviews(place.place_id, place.name, windowKey); setActiveReview({ place, reviews: response.reviews }) } catch (cause) { setError(cause instanceof Error ? cause.message : 'Reviews could not be loaded.'); setActiveReview(null) } finally { setReviewLoading(false) } }
  const openReviews = async (place: Place | Entity) => { await loadReviews(place, reviewWindow) }
  const changeReviewWindow = async (windowKey: ReviewWindowKey) => { setReviewWindow(windowKey); if (activeReview) await loadReviews(activeReview.place, windowKey) }
  return <div className="min-h-screen bg-[#f7f9fc] text-[#172033]"><Header step={step} hasReport={Boolean(report)} setStep={setStep} loading={loading} /><main className="mx-auto max-w-7xl px-5 lg:px-8"><div className="grid gap-8 lg:grid-cols-[220px_1fr]"><Stepper step={step} /><div>{step !== 'report' && <SummaryBar draft={draft} />}{step === 'setup' && <SetupStep draft={draft} update={update} ownQuery={ownQuery} setOwnQuery={setOwnQuery} ownResults={ownResults} setOwnResults={setOwnResults} runOwnSearch={runOwnSearch} loading={loading} ownSearchLoading={ownSearchLoading} competitorSearchLoading={competitorSearchLoading} onNext={runCompetitorSearch} error={error} config={config} />}{step === 'discover' && <BusinessPicker places={places} selected={draft.competitors} toggle={toggleCompetitor} max={config.limits.max_competitors} onBack={() => setStep('setup')} onNext={() => setStep('options')} error={error} />}{step === 'options' && <OptionsStep draft={draft} update={update} config={config} onBack={() => setStep('discover')} onGenerate={runAnalysis} loading={loading} progress={progress} error={error} />}{step === 'report' && report && <ReportView report={report} onNew={() => { setReport(null); setStep('setup') }} openReviews={openReviews} reviewWindow={reviewWindow} setReviewWindow={setReviewWindow} />}</div></div></main>{activeReview && <ReviewDrawer state={activeReview} windowKey={reviewWindow} onWindowChange={changeReviewWindow} loading={reviewLoading} close={() => setActiveReview(null)} />}</div>}
function Header({ step, hasReport, setStep, loading }: { step: Step; hasReport: boolean; setStep: (step: Step) => void; loading: boolean }) { return <header className="border-b border-[#dfe5ec] bg-white"><div className="mx-auto flex max-w-7xl items-center justify-between px-5 py-4 lg:px-8"><button onClick={() => setStep('setup')} disabled={loading} className="flex items-center gap-3 disabled:cursor-wait" aria-label="Go to dashboard"><span className="grid h-10 w-10 place-items-center rounded-xl bg-[#0f2747] text-white shadow-[0_5px_0_#0f8b8d]"><span className="font-serif text-xl">D</span></span><div className="text-left"><div className="font-serif text-2xl font-semibold text-[#0f2747]">MarketLens</div><div className="text-[10px] font-semibold uppercase tracking-[0.2em] text-[#667085]">local intelligence</div></div></button><nav className="hidden items-center gap-7 text-sm font-medium text-[#667085] md:flex"><button onClick={() => setStep('setup')} disabled={loading} className="hover:text-[#0f8b8d] disabled:cursor-wait disabled:opacity-50">Dashboard</button><button onClick={() => setStep('discover')} disabled={loading} className="hover:text-[#0f8b8d] disabled:cursor-wait disabled:opacity-50">Businesses</button><button onClick={() => hasReport && setStep('report')} disabled={!hasReport || loading} className="hover:text-[#0f8b8d] disabled:opacity-40">Reports</button></nav><button onClick={() => setStep('setup')} disabled={loading} className="inline-flex items-center gap-2 rounded-lg bg-[#0f2747] px-4 py-2.5 text-sm font-semibold text-white hover:bg-[#173b68] disabled:cursor-wait disabled:opacity-50"><Search size={15} /> New scan</button></div>{loading && <AnalysisLoader progress={0} />}</header> }
function Stepper({ step }: { step: Step }) { const steps = [['setup', 'Your business'], ['discover', 'Find businesses'], ['options', 'Report options'], ['report', 'Report']]; return <aside className="hidden pt-10 lg:block"><div className="sticky top-5"><p className="text-xs font-bold uppercase tracking-[0.18em] text-[#667085]">Workspace</p><div className="mt-5 space-y-2">{steps.map(([key, label], index) => { const active = key === step; return <div key={key} className={`flex items-center gap-3 rounded-lg px-3 py-3 text-sm ${active ? 'bg-[#d9f3f0] font-semibold text-[#0f2747]' : 'text-[#667085]'}`}><span className={`grid h-7 w-7 place-items-center rounded-lg text-xs font-bold ${active ? 'bg-[#0f8b8d] text-white' : 'bg-[#eef2f6]'}`}>{index + 1}</span>{label}</div> })}</div></div></aside> }
function SummaryBar({ draft }: { draft: Draft }) { return <div className="mb-6 flex flex-wrap items-center gap-2 border-b border-[#dfe5ec] py-4 text-sm text-[#667085]"><span className="font-semibold text-[#0f2747]">{draft.businessType || 'Business scan'}</span><span>·</span><span>{[draft.area, draft.city, draft.country].filter(Boolean).join(', ') || 'Location not set'}</span>{draft.ownBusiness && <span className="rounded-full bg-[#d9f3f0] px-3 py-1 text-xs font-semibold text-[#0f6f72]">Comparing against: {draft.ownBusiness.name}</span>}</div> }
function Field({ label, value, onChange, placeholder, required, disabled }: { label: string; value: string; onChange: (value: string) => void; placeholder?: string; required?: boolean; disabled?: boolean }) { return <label className="block text-sm font-semibold text-[#172033]">{label}{required && <span className="ml-1 text-[#d64545]">*</span>}<input value={value} onChange={(event) => onChange(event.target.value)} placeholder={placeholder} disabled={disabled} className="mt-2 w-full rounded-lg border border-[#dfe5ec] bg-[#f7f9fc] px-3 py-3 font-normal text-[#172033] outline-none focus:border-[#0f8b8d] focus:ring-2 focus:ring-[#d9f3f0] disabled:opacity-60" /></label> }
function SetupStep({ draft, update, ownQuery, setOwnQuery, ownResults, setOwnResults, runOwnSearch, loading, ownSearchLoading, competitorSearchLoading, onNext, error, config }: any) { return <section className="pb-20 pt-8"><div className="rounded-2xl border border-[#dfe5ec] bg-white p-6 shadow-sm sm:p-9"><p className="text-xs font-bold uppercase tracking-[0.18em] text-[#0f8b8d]">01 / Your business</p><h1 className="mt-3 font-serif text-4xl tracking-[-0.04em] text-[#0f2747]">Start with your market.</h1><p className="mt-3 max-w-2xl leading-7 text-[#667085]">Tell us what you operate and where. Add your own business for a clear “You vs Market” report, or skip it for a market overview.</p><div className="mt-8 grid gap-4 sm:grid-cols-2"><div><Field label="Business type" value={draft.businessType} onChange={(value) => update({ businessType: value })} placeholder="e.g. restaurant, gym, salon" required disabled={competitorSearchLoading} /><div className="mt-3 flex flex-wrap gap-2">{config.business_type_suggestions.slice(0, 6).map((item: string) => <button key={item} onClick={() => update({ businessType: item })} disabled={competitorSearchLoading} className="rounded-full border border-[#b9dedd] px-3 py-1.5 text-xs font-medium text-[#0f6f72] hover:bg-[#edfafa] disabled:opacity-60">{item}</button>)}</div></div><Field label="City" value={draft.city} onChange={(value) => update({ city: value })} placeholder="City" required disabled={competitorSearchLoading} /><Field label="Country" value={draft.country} onChange={(value) => update({ country: value })} placeholder="Country" required disabled={competitorSearchLoading} /><Field label="Area (optional)" value={draft.area} onChange={(value) => update({ area: value })} placeholder="Leave empty to search the whole city" disabled={competitorSearchLoading} /></div><div className="mt-9 border-t border-[#edf0f4] pt-7"><div className="flex items-start justify-between gap-4"><div><h2 className="font-semibold text-[#0f2747]">Find your own business <span className="font-normal text-[#667085]">(recommended)</span></h2><p className="mt-1 text-sm text-[#667085]">We’ll compare every selected business against you.</p></div></div><div className="mt-4 flex gap-2"><input value={ownQuery} onChange={(event) => setOwnQuery(event.target.value)} onKeyDown={(event) => event.key === 'Enter' && !ownSearchLoading && runOwnSearch()} disabled={ownSearchLoading} placeholder="Search by business name" className="min-w-0 flex-1 rounded-lg border border-[#dfe5ec] bg-[#f7f9fc] px-3 py-3 outline-none focus:border-[#0f8b8d] disabled:opacity-60" /><button onClick={runOwnSearch} disabled={ownSearchLoading} className="inline-flex min-w-[100px] items-center justify-center gap-2 rounded-lg bg-[#0f2747] px-4 py-3 text-sm font-semibold text-white disabled:opacity-50">{ownSearchLoading ? <><RefreshCw size={15} className="animate-spin" /> Searching…</> : <><Search size={15} /> Search</>}</button></div>{ownSearchLoading && <div className="mt-4 grid gap-3">{[0, 1].map((i) => <div key={i} className="animate-pulse rounded-lg border border-[#dfe5ec] bg-[#f7f9fc] p-4"><div className="h-4 w-1/3 rounded bg-[#dfe5ec]" /><div className="mt-2 h-3 w-2/3 rounded bg-[#dfe5ec]" /></div>)}</div>}{!ownSearchLoading && ownResults.length > 0 && <div className="mt-4 grid gap-3">{ownResults.map((place: Place) => <button key={place.place_id} onClick={() => { update({ ownBusiness: place }); setOwnResults([]) }} className="flex items-center justify-between rounded-lg border border-[#dfe5ec] bg-[#f7f9fc] p-4 text-left hover:border-[#0f8b8d]"><div><div className="font-semibold text-[#172033]">{place.name}</div><div className="mt-1 text-sm text-[#667085]">{address(place)}</div></div><div className="text-right text-sm"><div className="flex items-center gap-1 text-[#f5a623]"><Star size={13} fill="currentColor" /> {number(place.rating)}</div><div className="mt-1 text-[#667085]">{number(place.reviews_count)} reviews</div></div></button>)}</div>}{draft.ownBusiness && <div className="mt-4 flex items-center justify-between rounded-lg bg-[#edfafa] p-4 text-sm"><span className="font-semibold text-[#0f6f72]">Selected: {draft.ownBusiness.name}</span><button onClick={() => update({ ownBusiness: null })} className="text-[#667085] hover:text-[#d64545]">Remove</button></div>}</div>{error && <ErrorBanner message={error} />}</div><div className="mt-5 flex justify-end"><button onClick={onNext} disabled={competitorSearchLoading} className="inline-flex min-w-[200px] items-center justify-center gap-2 rounded-lg bg-[#0f2747] px-5 py-3 font-semibold text-white hover:bg-[#173b68] disabled:opacity-50">{competitorSearchLoading ? <><RefreshCw size={16} className="animate-spin" /> Finding businesses…</> : <>Find businesses <ArrowRight size={16} /></>}</button></div></section> }
function DiscoverStep({ draft, places, toggle, onBack, onNext, error }: any) { return <section className="pb-20 pt-8"><div className="flex items-end justify-between gap-4"><div><p className="text-xs font-bold uppercase tracking-[0.18em] text-[#0f8b8d]">02 / Find businesses</p><h1 className="mt-2 font-serif text-4xl text-[#0f2747]">Potential competitors</h1><p className="mt-2 text-[#667085]">Review the local results before choosing your comparison set.</p></div><span className="rounded-full bg-[#d9f3f0] px-3 py-1.5 text-xs font-semibold text-[#0f6f72]">{places.length} found</span></div>{error && <div className="mt-5"><ErrorBanner message={error} /></div>}<div className="mt-6 overflow-hidden rounded-xl border border-[#dfe5ec] bg-white"><div className="hidden overflow-x-auto md:block"><table className="w-full min-w-[900px] text-left text-sm"><thead className="bg-[#f7f9fc] text-xs uppercase tracking-wider text-[#667085]"><tr>{['Business', 'Address', 'Contact', 'Rating', 'Reviews', 'Rank', 'Status'].map((label) => <th key={label} className="px-4 py-3 font-semibold">{label}</th>)}</tr></thead><tbody>{places.map((place: Place) => <PlaceRow key={place.place_id} place={place} selected={draft.competitors.some((item: Place) => item.place_id === place.place_id)} toggle={toggle} />)}</tbody></table></div><div className="grid gap-3 p-3 md:hidden">{places.map((place: Place) => <PlaceCard key={place.place_id} place={place} selected={draft.competitors.some((item: Place) => item.place_id === place.place_id)} toggle={toggle} />)}</div></div><div className="mt-5 flex justify-between"><button onClick={onBack} className="inline-flex items-center gap-2 text-sm font-semibold text-[#667085]"><ArrowLeft size={15} /> Back</button><button onClick={onNext} className="inline-flex items-center gap-2 rounded-lg bg-[#0f2747] px-5 py-3 text-sm font-semibold text-white">Select competitors <ArrowRight size={15} /></button></div></section> }
function PlaceRow({ place, selected, toggle }: { place: Place; selected: boolean; toggle: (place: Place) => void }) { return <tr className="border-t border-[#edf0f4]"><td className="px-4 py-4"><button onClick={() => toggle(place)} className={`mr-3 inline-grid h-5 w-5 place-items-center rounded border ${selected ? 'border-[#0f8b8d] bg-[#0f8b8d] text-white' : 'border-[#cbd5e1]'}`}>{selected && <Check size={13} />}</button><span className="font-semibold text-[#172033]">{place.name}</span>{place.is_permanently_closed || place.is_temporarily_closed ? <span className="ml-2 rounded-full bg-[#fff0f0] px-2 py-1 text-[10px] font-bold text-[#d64545]">Closed</span> : null}<div className="mt-1 text-xs text-[#667085]">{place.category || 'Business'}</div></td><td className="max-w-xs px-4 py-4 text-[#667085]">{address(place)}</td><td className="px-4 py-4 text-xs text-[#667085]">{place.phone || '—'}{safeUrl(place.website) && <a className="mt-1 block text-[#0f8b8d]" href={safeUrl(place.website)!} target="_blank" rel="noopener noreferrer">Website</a>}</td><td className="px-4 py-4"><span className="flex items-center gap-1 text-[#f5a623]"><Star size={13} fill="currentColor" />{number(place.rating)}</span></td><td className="px-4 py-4 text-[#667085]">{number(place.reviews_count)}</td><td className="px-4 py-4 text-[#667085]">#{place.search_rank}</td><td className="px-4 py-4 text-xs text-[#667085]">{place.distance_km !== null ? `${place.distance_km} km` : '—'}{safeUrl(place.google_maps_url) && <a className="mt-1 block text-[#0f8b8d]" href={safeUrl(place.google_maps_url)!} target="_blank" rel="noopener noreferrer">Maps</a>}</td></tr> }
function PlaceCard({ place, selected, toggle }: { place: Place; selected: boolean; toggle: (place: Place) => void }) { return <article className={`rounded-lg border p-4 ${selected ? 'border-[#0f8b8d] bg-[#edfafa]' : 'border-[#dfe5ec]'}`}><div className="flex justify-between gap-3"><button onClick={() => toggle(place)} className="flex items-start gap-3 text-left"><span className={`grid h-6 w-6 shrink-0 place-items-center rounded border ${selected ? 'border-[#0f8b8d] bg-[#0f8b8d] text-white' : 'border-[#cbd5e1]'}`}>{selected && <Check size={13} />}</span><span><strong className="text-[#172033]">{place.name}</strong><span className="mt-1 block text-sm text-[#667085]">{address(place)}</span></span></button><span className="flex items-center gap-1 text-sm text-[#f5a623]"><Star size={13} fill="currentColor" />{number(place.rating)}</span></div><div className="mt-4 flex justify-between text-xs text-[#667085]"><span>{number(place.reviews_count)} reviews</span><span>Rank #{place.search_rank}</span><span>{place.distance_km !== null ? `${place.distance_km} km` : '—'}</span></div></article> }
function SelectStep({ draft, places, toggle, max, onBack, onNext, error }: any) { return <section className="pb-20 pt-8"><p className="text-xs font-bold uppercase tracking-[0.18em] text-[#0f8b8d]">03 / Select set</p><div className="flex flex-col justify-between gap-4 sm:flex-row sm:items-end"><div><h1 className="mt-2 font-serif text-4xl text-[#0f2747]">Choose your comparison set</h1><p className="mt-2 text-[#667085]">Select any number from 1 to {max}. Keep the set focused enough to act on.</p></div><div className="rounded-xl bg-[#0f2747] px-5 py-3 text-white"><strong className="text-2xl">{draft.competitors.length}</strong><span className="ml-1 text-sm text-[#c8d4e2]">selected</span></div></div>{error && <div className="mt-5"><ErrorBanner message={error} /></div>}<div className="mt-6 grid gap-3">{places.map((place: Place) => <PlaceCard key={place.place_id} place={place} selected={draft.competitors.some((item: Place) => item.place_id === place.place_id)} toggle={toggle} />)}</div><div className="sticky bottom-4 mt-8 flex justify-between rounded-xl border border-[#dfe5ec] bg-white/95 p-4 shadow-lg backdrop-blur"><button onClick={onBack} className="inline-flex items-center gap-2 text-sm font-semibold text-[#667085]"><ArrowLeft size={15} /> Back</button><button onClick={onNext} disabled={draft.competitors.length < 1} className="inline-flex items-center gap-2 rounded-lg bg-[#0f2747] px-5 py-3 text-sm font-semibold text-white disabled:opacity-40">Continue <ArrowRight size={15} /></button></div></section> }
function OptionsStep({ draft, update, config, onBack, onGenerate, loading, progress, error }: any) { const stages = ['Collecting profiles & reviews', 'Calculating statistics', 'Analysing customer feedback', 'Building your strategy']; return <section className="pb-20 pt-8"><p className="text-xs font-bold uppercase tracking-[0.18em] text-[#0f8b8d]">04 / Report options</p><h1 className="mt-2 font-serif text-4xl text-[#0f2747]">Tune the report to your goals.</h1><p className="mt-3 text-[#667085]">The default 30-day window is fastest. All available reviews gives broader context but takes longer.</p><div className="mt-7 grid gap-6 lg:grid-cols-[1fr_300px]"><div className="space-y-6"><div className="rounded-xl border border-[#dfe5ec] bg-white p-5"><h2 className="font-semibold text-[#0f2747]">Review period</h2><div className="mt-4 grid grid-cols-2 gap-2 sm:grid-cols-4">{config.review_windows.map((window: any) => <button key={window.key} onClick={() => update({ reviewWindow: window.key })} className={`rounded-lg border px-3 py-3 text-sm font-semibold ${draft.reviewWindow === window.key ? 'border-[#0f8b8d] bg-[#d9f3f0] text-[#0f6f72]' : 'border-[#dfe5ec] text-[#667085]'}`}>{window.label}</button>)}</div></div><div className="rounded-xl border border-[#dfe5ec] bg-white p-5"><h2 className="font-semibold text-[#0f2747]">Goals</h2><div className="mt-4 flex flex-wrap gap-2">{config.goal_suggestions.map((goal: string) => <button key={goal} onClick={() => update({ goals: draft.goals.includes(goal) ? draft.goals.filter((item: string) => item !== goal) : [...draft.goals, goal] })} className={`rounded-full border px-3 py-2 text-sm ${draft.goals.includes(goal) ? 'border-[#0f8b8d] bg-[#d9f3f0] text-[#0f6f72]' : 'border-[#dfe5ec] text-[#667085]'}`}>{draft.goals.includes(goal) && <Check size={13} className="mr-1 inline" />}{goal}</button>)}</div></div><div className="rounded-xl border border-[#dfe5ec] bg-white p-5"><label className="font-semibold text-[#0f2747]">Owner context <span className="font-normal text-[#667085]">(optional)</span><textarea value={draft.ownerContext} maxLength={1500} onChange={(event) => update({ ownerContext: event.target.value })} placeholder="Tell us what matters to your business..." className="mt-3 min-h-28 w-full rounded-lg border border-[#dfe5ec] bg-[#f7f9fc] p-3 font-normal outline-none focus:border-[#0f8b8d]" /></label><div className="mt-1 text-right text-xs text-[#667085]">{draft.ownerContext.length}/1500</div></div></div><aside className="h-fit rounded-xl bg-[#0f2747] p-5 text-white"><div className="flex items-center gap-2 text-[#b6ebe5]"><Target size={17} /> Analysis summary</div><h2 className="mt-4 font-serif text-2xl">{draft.competitors.length} businesses</h2><p className="mt-2 text-sm leading-6 text-[#c8d4e2]">{draft.reviewWindow === 'all' ? 'All available reviews' : `Reviews from the last ${draft.reviewWindow.replace('d', ' days')}`} · {draft.ownBusiness ? `Compared with ${draft.ownBusiness.name}` : 'Market overview'}</p><button onClick={onGenerate} disabled={loading} className="mt-8 inline-flex w-full items-center justify-center gap-2 rounded-lg bg-white px-4 py-3 font-semibold text-[#0f2747] disabled:opacity-50">{loading ? <><Sparkles size={16} className="animate-pulse" /> Preparing...</> : <>Generate report <ArrowRight size={15} /></>}</button>{loading && <div className="mt-6 space-y-3">{stages.map((stage, index) => <div key={stage} className={`flex items-center gap-2 text-xs ${index <= progress ? 'text-white' : 'text-[#7890a8]'}`}>{index < progress ? <CheckCircle2 size={14} /> : <span className="grid h-3.5 w-3.5 place-items-center rounded-full border border-current" />}{stage}</div>)}</div>}{error && <div className="mt-5"><ErrorBanner message={error} dark /></div>}</aside></div><button onClick={onBack} className="mt-6 inline-flex items-center gap-2 text-sm font-semibold text-[#667085]"><ArrowLeft size={15} /> Back</button></section> }
function AnalysisLoader({ progress }: { progress: number }) { const stages = ['Collecting profiles & reviews', 'Calculating statistics', 'Analysing customer feedback', 'Building your strategy']; const [activeStage, setActiveStage] = useState(progress); useEffect(() => { const timer = window.setInterval(() => setActiveStage((value) => Math.min(value + 1, stages.length - 1)), 18000); return () => window.clearInterval(timer) }, [stages.length]); return <div className="analysis-loader fixed inset-0 z-40 grid place-items-center bg-[#0f2747]/55 p-5" role="status" aria-live="polite"><div className="w-full max-w-md rounded-2xl bg-white p-7 text-center shadow-2xl"><div className="mx-auto grid h-14 w-14 place-items-center rounded-full bg-[#d9f3f0] text-[#0f8b8d]"><Sparkles size={26} className="animate-pulse" /></div><h2 className="mt-5 font-serif text-2xl text-[#0f2747]">Preparing your market report</h2><p className="mt-2 text-sm leading-6 text-[#667085]">Please keep this window open while we analyse the selected businesses.</p><div className="mt-6 space-y-3 text-left">{stages.map((stage, index) => <div key={stage} className={`flex items-center gap-3 rounded-lg px-3 py-2 text-sm ${index < activeStage ? 'bg-[#e6f6ee] text-[#1d8a5b]' : index === activeStage ? 'bg-[#d9f3f0] font-semibold text-[#0f6f72]' : 'text-[#98a2b3]'}`}>{index < activeStage ? <CheckCircle2 size={16} /> : index === activeStage ? <RefreshCw size={16} className="animate-spin" /> : <span className="h-4 w-4 rounded-full border border-current" />}{stage}</div>)}</div></div></div> }
function ErrorBanner({ message, dark = false }: { message: string; dark?: boolean }) { return <div className={`flex items-start gap-2 rounded-lg p-3 text-sm ${dark ? 'bg-white/10 text-[#ffd3d3]' : 'bg-[#fff0f0] text-[#d64545]'}`}><CircleAlert size={16} className="mt-0.5 shrink-0" />{message}</div> }
function ReportView({ report, onNew, openReviews, reviewWindow, setReviewWindow }: { report: Report; onNew: () => void; openReviews: (entity: Entity) => void; reviewWindow: ReviewWindowKey; setReviewWindow: (value: ReviewWindowKey) => void }) { const [tab, setTab] = useState('summary'); const ai = report.ai; const own = report.entities.find((entity) => entity.role === 'own'); const download = (type: 'json' | 'csv') => { const payload = type === 'json' ? JSON.stringify(report, null, 2) : [['Business', 'Role', 'Rating', 'Reviews', 'Address'].join(','), ...report.entities.map((entity) => [entity.name, entity.role, entity.lifetime.rating ?? '', entity.lifetime.reviews_count ?? '', address(entity)].map((value) => `"${String(value).replaceAll('"', '""')}"`).join(','))].join('\n'); const blob = new Blob([payload], { type: type === 'json' ? 'application/json' : 'text/csv' }); const link = document.createElement('a'); link.href = URL.createObjectURL(blob); link.download = `marketlens-report.${type}`; link.click(); URL.revokeObjectURL(link.href) }; const copySummary = () => navigator.clipboard?.writeText([ai?.executive_summary.headline, ai?.executive_summary.market_position_statement, ...(ai?.executive_summary.key_findings || []).slice(0, 3).map((item) => `• ${item.finding}`)].filter(Boolean).join('\n\n')); return <section className="report-workspace min-w-0 pb-24 pt-8"><div className="no-print flex flex-col justify-between gap-5 border-b border-[#dfe5ec] pb-7 sm:flex-row sm:items-end"><div><p className="text-xs font-bold uppercase tracking-[0.18em] text-[#0f8b8d]">Report · {report.meta.review_window.label}</p><h1 className="mt-2 font-serif text-4xl text-[#0f2747]">{report.meta.location.city} market report</h1><p className="mt-2 text-[#667085]">{report.meta.business_type} · {report.meta.comparison_mode.replaceAll('_', ' ')}</p></div><div className="flex flex-wrap gap-2"><button onClick={onNew} className="rounded-lg border border-[#dfe5ec] bg-white px-3 py-2 text-sm font-semibold text-[#667085]">New scan</button><button onClick={() => window.print()} className="inline-flex items-center gap-2 rounded-lg bg-[#0f2747] px-3 py-2 text-sm font-semibold text-white"><Download size={15} /> PDF</button><button onClick={() => download('csv')} className="rounded-lg border border-[#b9dedd] bg-white px-3 py-2 text-sm font-semibold text-[#0f6f72]">CSV</button><button onClick={() => download('json')} className="rounded-lg border border-[#b9dedd] bg-white px-3 py-2 text-sm font-semibold text-[#0f6f72]">JSON</button><button onClick={copySummary} className="rounded-lg border border-[#b9dedd] bg-white px-3 py-2 text-sm font-semibold text-[#0f6f72]"><Clipboard size={15} /></button></div></div><div className="print-header mt-4"><strong className="font-serif text-2xl text-[#0f2747]">MarketLens</strong><span className="text-sm text-[#667085]">{report.meta.business_type} · {report.meta.location.city}</span></div><div className="report-screen">{ai && <section className="mt-6 rounded-2xl bg-[#0f2747] p-6 text-white sm:p-8"><span className="rounded-full bg-white/10 px-3 py-1.5 text-xs font-semibold uppercase tracking-wider text-[#b6ebe5]">{ai.executive_summary.overall_verdict}</span><h2 className="mt-5 max-w-3xl font-serif text-3xl leading-tight sm:text-4xl">{ai.executive_summary.headline}</h2><p className="mt-4 max-w-3xl text-[#c8d4e2]">{ai.executive_summary.market_position_statement}</p><div className="mt-6 grid gap-3 md:grid-cols-3">{ai.executive_summary.key_findings.slice(0, 3).map((finding) => <div key={finding.finding} className="rounded-lg bg-white/10 p-4"><span className="text-xs font-semibold uppercase tracking-wider text-[#b6ebe5]">{finding.importance}</span><p className="mt-2 text-sm leading-6">{finding.finding}</p></div>)}</div></section>}{!ai && <div className="mt-6"><ErrorBanner message={report.data_quality.ai_message || 'AI strategy was unavailable. Numeric and profile sections are still available.'} /></div>}<div className="mt-6 flex gap-2 overflow-x-auto border-b border-[#dfe5ec] pb-2">{[['summary', 'Summary'], ['benchmark', 'You vs Market'], ['themes', 'Customer themes'], ['content', 'Content intelligence'], ['actions', 'Action plan'], ['profiles', 'Profiles']].map(([key, label]) => <button key={key} onClick={() => setTab(key)} className={`whitespace-nowrap rounded-lg px-3 py-2 text-sm font-semibold ${tab === key ? 'bg-[#0f2747] text-white' : 'text-[#667085] hover:bg-white'}`}>{label}</button>)}</div>{tab === 'summary' && <><ReportVisuals report={report} /><SummaryReport report={report} /></>}{tab === 'benchmark' && <BenchmarkSection report={report} own={own} />}{tab === 'themes' && <ThemesSection report={report} />}{tab === 'content' && <ContentIntelligence report={report} />}{tab === 'actions' && <ActionsSection ai={ai} />}{tab === 'profiles' && <ProfilesSection report={report} openReviews={openReviews} reviewWindow={reviewWindow} setReviewWindow={setReviewWindow} />}{tab === 'quality' && <QualityPanel report={report} />}</div><PrintReport report={report} own={own} /></section> }

function PrintReport({ report, own }: { report: Report; own?: Entity }) { return <div className="print-report report-document"><div className="mt-6">{report.ai && <section className="rounded-2xl bg-[#0f2747] p-6 text-white"><span className="text-xs font-semibold uppercase tracking-wider text-[#b6ebe5]">{report.ai.executive_summary.overall_verdict}</span><h2 className="mt-4 font-serif text-3xl">{report.ai.executive_summary.headline}</h2><p className="mt-3 leading-7 text-[#c8d4e2]">{report.ai.executive_summary.market_position_statement}</p></section>}<ReportVisuals report={report} /><SummaryReport report={report} /><BenchmarkSection report={report} own={own} /><ThemesSection report={report} /><ContentIntelligence report={report} /><ActionsSection ai={report.ai} /><ProfilesSection report={report} openReviews={() => undefined} reviewWindow={report.meta.review_window.key} setReviewWindow={() => undefined} /></div></div> }
function SummaryReport({ report }: { report: Report }) { return <div className="mt-6 grid gap-6 lg:grid-cols-[1fr_1fr]"><section className="rounded-xl border border-[#dfe5ec] bg-white p-5"><div className="flex items-center gap-2 text-[#0f8b8d]"><Gauge size={18} /><h2 className="font-semibold text-[#0f2747]">Market scoreboard</h2></div><div className="mt-5 grid gap-4 sm:grid-cols-2">{report.benchmark.leaderboard.map((row) => <div key={row.place_id} className={`flex items-center justify-between rounded-lg p-3 ${row.role === 'own' ? 'bg-[#d9f3f0]' : 'bg-[#f7f9fc]'}`}><div><span className="text-xs font-bold text-[#667085]">#{row.rank}</span><div className="font-semibold text-[#172033]">{row.name}</div></div><div className="text-right text-xl font-semibold text-[#0f2747]">{row.health_score ?? '—'}</div></div>)}</div></section><section className="rounded-xl border border-[#dfe5ec] bg-white p-5"><div className="flex items-center gap-2 text-[#0f8b8d]"><TrendingUp size={18} /><h2 className="font-semibold text-[#0f2747]">Where to focus</h2></div><div className="mt-4 space-y-3">{(report.benchmark.gaps.length ? report.benchmark.gaps : report.benchmark.advantages).slice(0, 5).map((gap) => <div key={gap.key} className="rounded-lg bg-[#f7f9fc] p-3 text-sm"><div className="font-semibold text-[#172033]">{gap.label}</div><div className="mt-1 text-[#667085]">You: {gap.you ?? '—'} · Market: {gap.competitor_avg ?? '—'} · Best: {gap.best_name}</div></div>)}</div></section></div> }
function BenchmarkSection({ report, own }: { report: Report; own?: Entity }) { return <div className="mt-6 space-y-6">{!own && <ErrorBanner message="This is a market overview. Add your business in a new scan to unlock You vs Market comparisons." />}<section className="overflow-hidden rounded-xl border border-[#dfe5ec] bg-white p-5"><div className="flex flex-wrap items-end justify-between gap-3"><div><h2 className="font-semibold text-[#0f2747]">Benchmark metrics</h2><p className="mt-1 text-sm text-[#667085]">How you stack up against the market on each signal.</p></div><div className="flex items-center gap-3 text-[11px] font-semibold uppercase tracking-wider text-[#667085]"><span className="flex items-center gap-1"><span className="h-2 w-2 rounded-full bg-[#22a06b]" />Leading</span><span className="flex items-center gap-1"><span className="h-2 w-2 rounded-full bg-[#f5a623]" />Parity</span><span className="flex items-center gap-1"><span className="h-2 w-2 rounded-full bg-[#d64545]" />Behind</span></div></div><div className="mt-5 overflow-x-auto"><table className="w-full min-w-[760px] text-left text-sm"><thead><tr className="border-b border-[#edf0f4] text-[11px] uppercase tracking-wider text-[#667085]"><th className="pb-3 font-semibold">Metric</th><th className="pb-3 font-semibold">You</th><th className="pb-3 font-semibold">Market avg</th><th className="pb-3 font-semibold">Best in market</th><th className="pb-3 text-right font-semibold">Verdict</th></tr></thead><tbody>{report.benchmark.metrics.map((metric) => { const unavailable = metric.you === null || metric.you === undefined; const verdict = unavailable ? null : metric.verdict; const leading = verdict === 'leading'; const behind = verdict === 'behind'; const tone = leading ? 'bg-[#e6f6ee]/60' : behind ? 'bg-[#fff0f0]/60' : ''; const pill = unavailable ? 'bg-[#eef2f6] text-[#667085]' : leading ? 'bg-[#e6f6ee] text-[#1d8a5b]' : behind ? 'bg-[#fff0f0] text-[#c53b3b]' : 'bg-[#fff4df] text-[#a76b00]'; const icon = unavailable ? '—' : leading ? '↑' : behind ? '↓' : '→'; const label = unavailable ? 'Not available' : leading ? 'Leading' : behind ? 'Behind' : 'Parity'; return <tr key={metric.key} className="border-b border-[#edf0f4] last:border-0 transition hover:bg-[#faf3fb]"><td className="py-4 pr-3"><div className="font-semibold text-[#172033]">{metric.label}</div>{metric.unit && <div className="mt-0.5 text-[11px] text-[#98a2b3]">measured in {metric.unit}</div>}</td><td className={`py-4 pr-3 ${tone} rounded-l-lg`}><div className="pl-3 font-semibold text-[#172033]">{metric.you !== null && metric.you !== undefined ? <>{metric.you}<span className="text-[#667085]">{metric.unit}</span></> : <span className="text-[#98a2b3]">—</span>}</div></td><td className="py-4 pr-3"><div className="text-[#667085]">{metric.competitor_avg !== null && metric.competitor_avg !== undefined ? <>{metric.competitor_avg}{metric.unit}</> : '—'}</div></td><td className="py-4 pr-3"><div className="text-xs font-semibold text-[#172033]">{metric.best.name}</div><div className="mt-0.5 text-xs text-[#667085]">{metric.best.value !== null && metric.best.value !== undefined ? <>{metric.best.value}{metric.unit}</> : '—'}</div></td><td className={`py-4 text-right ${tone} rounded-r-lg`}><span className={`mr-3 inline-flex items-center gap-1 rounded-full px-2.5 py-1 text-[11px] font-bold uppercase tracking-wider ${pill}`}><span aria-hidden>{icon}</span>{label}</span></td></tr> }) }</tbody></table></div></section></div> }

function ThemesSection({ report }: { report: Report }) {
  const { taxonomy, rows } = report.theme_matrix;

  return (
    <div className="theme-matrix mt-6 min-w-0">
      <section className="overflow-hidden rounded-xl border border-[#dfe5ec] bg-white">
        <div className="border-b border-[#dfe5ec] p-5">
          <h2 className="font-semibold text-[#0f2747]">
            What customers talk about
          </h2>
          <p className="mt-1 text-sm text-[#667085]">
            Customer sentiment across the main discussion themes.
          </p>
        </div>

        <table className="theme-matrix-table w-full table-fixed border-collapse text-sm">
          <colgroup>
            <col className="w-36 sm:w-44" />
            {taxonomy.map((theme) => (
              <col key={theme.key} />
            ))}
          </colgroup>

          <thead>
            <tr className="bg-[#f8fafc]">
              <th className="border-b border-r border-[#dfe5ec] bg-[#f8fafc] px-4 py-3 text-left text-xs font-semibold uppercase tracking-wide text-[#667085]">
                Business
              </th>

              {taxonomy.map((theme) => (
                <th
                  key={theme.key}
                  title={theme.label}
                  className="min-w-0 border-b border-[#dfe5ec] px-1 py-3 text-center align-bottom text-[10px] font-semibold leading-tight text-[#667085] sm:px-1.5 sm:text-[11px]"
                >
                  <span className="block break-words">{theme.label}</span>
                </th>
              ))}
            </tr>
          </thead>

          <tbody>
            {rows.map((row) => (
              <tr key={row.place_id} className="transition-colors hover:bg-[#f8fafc]">
                <th className="border-b border-r border-[#e5e9ef] bg-white px-4 py-4 text-left font-semibold text-[#172033]">
                  <span className="block truncate" title={row.name}>
                    {row.name}
                  </span>
                </th>

                {taxonomy.map((theme) => {
                  const score = row.themes[theme.key];
                  const value = score?.net_pct ?? 0;
                  const isPositive = value >= 0;

                  return (
                    <td
                      key={theme.key}
                      title={`${theme.label}: ${score?.positive ?? 0} positive · ${score?.negative ?? 0} negative`}
                      className="min-w-0 border-b border-[#e5e9ef] px-0.5 py-4 text-center sm:px-1"
                    >
                      <span
                          className={`inline-flex max-w-full items-center justify-center rounded-md px-1 py-1 text-[10px] font-bold tabular-nums sm:px-1.5 sm:text-xs ${
                          isPositive
                            ? "bg-[#e8f6f4] text-[#0f8b8d]"
                            : "bg-[#fff0f0] text-[#d64545]"
                        }`}
                      >
                        {value > 0 ? "+" : ""}
                        {value}%
                      </span>
                    </td>
                  );
                })}
              </tr>
            ))}
          </tbody>
        </table>

        <div className="flex flex-wrap items-center gap-x-5 gap-y-2 border-t border-[#dfe5ec] bg-[#fbfcfe] px-4 py-3 text-xs text-[#667085]">
          <span className="font-medium">Net sentiment</span>
          <span className="flex items-center gap-1.5">
            <span className="h-2.5 w-2.5 rounded-sm bg-[#0f8b8d]" />
            Positive
          </span>
          <span className="flex items-center gap-1.5">
            <span className="h-2.5 w-2.5 rounded-sm bg-[#d64545]" />
            Negative
          </span>
          <span className="ml-auto">{taxonomy.length} themes</span>
        </div>
      </section>
    </div>
  );
}
function ActionsSection({ ai }: { ai: Report['ai'] }) { if (!ai) return <div className="mt-6"><ErrorBanner message="No action plan was generated because AI analysis was unavailable." /></div>; return <div className="mt-6 grid gap-4 md:grid-cols-3">{['7_days', '30_days', '90_days'].map((timeframe) => <section key={timeframe} className="rounded-xl border border-[#dfe5ec] bg-white p-5"><h2 className="font-semibold text-[#0f2747]">Next {timeframe.replace('_', ' ')}</h2><div className="mt-4 space-y-3">{ai.action_plan.filter((action) => action.timeframe === timeframe).map((action) => <div key={action.priority} className="rounded-lg bg-[#f7f9fc] p-4"><div className="flex justify-between gap-2"><span className="font-semibold text-[#172033]">{action.priority}. {action.title}</span><span className="text-xs text-[#0f8b8d]">{action.impact} impact</span></div><p className="mt-2 text-sm leading-6 text-[#667085]">{action.why}</p><p className="mt-3 text-xs font-semibold text-[#0f6f72]">KPI: {action.kpi}</p></div>)}</div></section>)}</div> }
function ProfilesSection({ report, openReviews }: { report: Report; openReviews: (entity: Entity) => void; reviewWindow: ReviewWindowKey; setReviewWindow: (value: ReviewWindowKey) => void }) { return <div className="mt-6 grid gap-4 md:grid-cols-2">{report.entities.map((entity) => <article key={entity.place_id} className="rounded-xl border border-[#dfe5ec] bg-white p-5"><div className="flex items-start justify-between gap-3"><div><span className="rounded-full bg-[#d9f3f0] px-2.5 py-1 text-xs font-semibold text-[#0f6f72]">{entity.role === 'own' ? 'You' : 'Competitor'}</span><h2 className="mt-3 font-semibold text-[#172033]">{entity.name}</h2><p className="mt-1 text-sm text-[#667085]">{text(entity.category)} · {address(entity)}</p></div><div className="text-right"><div className="text-2xl font-semibold text-[#0f2747]">{entity.health.score ?? '—'}</div><div className="text-xs text-[#667085]">health score</div></div></div>
<div className="mt-5 grid grid-cols-3 gap-2 text-center text-sm">
  <div className="rounded-lg bg-[#f0e5f2] p-3">
    <strong className="text-lg font-semibold text-[#2d1935]">{entity.lifetime.rating ?? '—'}</strong>
    <span className="mt-1 block text-[11px] font-medium uppercase tracking-wider text-[#78677d]">rating</span>
  </div>
  <div className="rounded-lg bg-[#f0e5f2] p-3">
    <strong className="text-lg font-semibold text-[#2d1935]">{number(entity.lifetime.reviews_count)}</strong>
    <span className="mt-1 block text-[11px] font-medium uppercase tracking-wider text-[#78677d]">reviews</span>
  </div>
  <div className="rounded-lg bg-[#f0e5f2] p-3">
    <strong className="text-lg font-semibold text-[#2d1935]">{entity.profile_completeness.score}%</strong>
    <span className="mt-1 block text-[11px] font-medium uppercase tracking-wider text-[#78677d]">profile</span>
  </div>
</div><button onClick={() => openReviews(entity)} className="no-print mt-5 w-full rounded-lg border border-[#b9dedd] px-3 py-2 text-sm font-semibold text-[#0f6f72] hover:bg-[#edfafa]">View reviews</button></article>)}</div> }

function ReviewDrawer({ state, windowKey, onWindowChange, loading, close }: { state: { place: Place | Entity; reviews: Review[] }; windowKey: ReviewWindowKey; onWindowChange: (value: ReviewWindowKey) => void | Promise<void>; loading: boolean; close: () => void }) { const [filter, setFilter] = useState(0); const reviews = filter ? state.reviews.filter((review) => review.rating === filter) : state.reviews; return <div className="fixed inset-0 z-50 bg-[#0f2747]/35" onClick={close}><aside onClick={(event) => event.stopPropagation()} className="absolute right-0 top-0 h-full w-full max-w-xl overflow-y-auto bg-[#f7f9fc] p-5 shadow-2xl sm:p-8"><div className="flex items-start justify-between border-b border-[#dfe5ec] pb-5"><div><span className="rounded-full bg-[#d9f3f0] px-3 py-1.5 text-xs font-semibold text-[#0f6f72]">Reviews</span><h2 className="mt-3 font-serif text-3xl text-[#0f2747]">{state.place.name}</h2></div><button onClick={close} className="grid h-9 w-9 place-items-center rounded-lg border border-[#dfe5ec] bg-white" aria-label="Close reviews"><X size={17} /></button></div><div className="mt-5 flex flex-wrap gap-2">{(['30d', '60d', '90d', 'all'] as ReviewWindowKey[]).map((key) => <button key={key} onClick={() => onWindowChange(key)} disabled={loading} className={`rounded-lg border px-3 py-2 text-xs font-semibold ${windowKey === key ? 'border-[#0f8b8d] bg-[#0f8b8d] text-white' : 'border-[#dfe5ec] bg-white text-[#667085]'}`}>{key === 'all' ? 'All' : key.replace('d', ' days')}</button>)}{[0, 5, 4, 3, 2, 1].map((value) => <button key={value} onClick={() => setFilter(value)} className={`rounded-lg border px-3 py-2 text-xs font-semibold ${filter === value ? 'border-[#0f2747] bg-[#0f2747] text-white' : 'border-[#dfe5ec] bg-white text-[#667085]'}`}>{value ? `${value}★` : 'All ratings'}</button>)}</div><div className="mt-5 space-y-3">{loading ? <div className="rounded-xl border border-[#dfe5ec] bg-white p-8 text-center text-sm text-[#78677d]">Loading reviews for this period...</div> : reviews.length ? reviews.map((review) => <article key={review.review_id} className="rounded-xl border border-[#dfe5ec] bg-white p-5"><div className="flex justify-between"><div><strong>{review.rating}/5</strong><div className="mt-1 text-xs text-[#667085]">{new Date(review.published_at).toLocaleDateString()} · {review.likes} likes</div></div><span className="flex text-[#f5a623]">{Array.from({ length: 5 }, (_, index) => <Star key={index} size={13} fill={index < review.rating ? 'currentColor' : 'none'} />)}</span></div><p className="mt-4 text-sm leading-6 text-[#667085]">{review.text}</p>{review.owner_reply ? <div className="mt-4 rounded-lg bg-[#edfafa] p-3 text-xs text-[#0f6f72]">Owner reply{review.reply_days !== null ? ` · replied in ${review.reply_days} days` : ''}: {review.owner_reply}</div> : <span className="mt-4 inline-block rounded-full bg-[#fff4df] px-2.5 py-1 text-xs font-semibold text-[#a76b00]">No reply</span>}</article>) : <div className="rounded-xl border border-dashed border-[#dfe5ec] bg-white p-10 text-center text-sm text-[#667085]">No reviews in this period. Try 90 days or All available.</div>}</div></aside></div> }